package com.example.transactionrecovery; import com.example.transactionrecovery.repository.*; import com.example.transactionrecovery.service.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.test.mock.mockito.SpyBean; import org.springframework.test.context.ActiveProfiles; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
@SpringBootTest @ActiveProfiles("test") class ApplicationCommandRollbackTest {@Autowired ApplicationCommandService commands;@Autowired ApplicationRepository apps;@Autowired SagaRepository sagas;@Autowired ProcessedEventRepository processed;@SpyBean OutboxRepository outbox;@Test void outboxFailureRollsBackWholeLocalTransaction(){processed.deleteAll();outbox.deleteAll();sagas.deleteAll();apps.deleteAll();doThrow(new RuntimeException("simulated storage failure")).when(outbox).save(any());assertThatThrownBy(()->commands.start("tenant-a",new ApplicationCommandService.StartRequest("BASIC",false,0))).isInstanceOf(IllegalStateException.class);assertThat(apps.count()).isZero();assertThat(sagas.count()).isZero();}}
